		if len(buf) == 0 {
			return
		}
		w := strings.ToLower(string(buf))
		buf = buf[:0]
		if _, ok := stopSet[w]; ok {
			return
		}
		counts[w]++
	}

	readErr := error(nil)
	for {
		c, err := rr.readRune()
		if err != nil {
